                cells.append((x, y))
                for nx, ny in ((x-1,y),(x+1,y),(x,y-1),(x,y+1)):
                    if (0 <= nx < h and 0 <= ny < w and
                        grid[nx][ny] != wall and (nx, ny) not in seen):
                        seen.add((nx, ny))
                        q.append((nx, ny))
            accents = Counter(grid[x][y] for x, y in cells
                              if grid[x][y] != bg)
            if accents:
                regions[(r, c)] = accents.most_common(1)[0][0]

    # Map every open cell to its component label.
    label = {}
    for start, color in regions.items():
        q = deque([start])
        label[start] = color
        while q:
