                    grid[nx][ny] != wall and (nx, ny) not in label):
                    label[(nx, ny)] = color
                    q.append((nx, ny))

    out = [row[:] for row in grid]
    for r in range(h):
        for c in range(w):
            if grid[r][c] != wall:
                continue
            around = [label[(nr, nc)] for nr, nc in
                      ((r-1,c),(r+1,c),(r,c-1),(r,c+1))
                      if (nr, nc) in label]
            if around:
                out[r][c] = Counter(around).most_common(1)[0][0]
    return out
