from collections import Counter, deque

def transform(grid):
    h, w = len(grid), len(grid[0])
    freq = Counter(v for row in grid for v in row)
    bg = freq.most_common(1)[0][0]
    wall = max((v for v in freq if v != bg), key=lambda v: freq[v])

    # Label the open regions separated by the maze walls.
    region = [[-1] * w for _ in range(h)]
    clues = []
    rid = 0
    for r in range(h):
        for c in range(w):
            if grid[r][c] == wall or region[r][c] != -1:
                continue
            q = deque([(r, c)])
            region[r][c] = rid
            cells = []
            while q:
                x, y = q.popleft()
                cells.append((x, y))
                for nx, ny in ((x-1,y),(x+1,y),(x,y-1),(x,y+1)):
                    if (0 <= nx < h and 0 <= ny < w and
                        grid[nx][ny] != wall and region[nx][ny] == -1):
                        region[nx][ny] = rid
                        q.append((nx, ny))
            colors = Counter(grid[x][y] for x, y in cells if grid[x][y] != bg)
            clues.append(colors)
            rid += 1

    out = [row[:] for row in grid]
    for r in range(h):
        for c in range(w):
            if grid[r][c] != wall:
                continue
            adj = set()
            for nr, nc in ((r-1,c),(r+1,c),(r,c-1),(r,c+1)):
                if 0 <= nr < h and 0 <= nc < w and region[nr][nc] >= 0:
                    adj.add(region[nr][nc])
            colors = Counter()
            for i in adj:
                colors.update(clues[i])
            if colors:
                out[r][c] = colors.most_common(1)[0][0]
    return out
